Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub)
WHERE (
  (
    (toLower(pub.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
    AND (
      (
        (toLower(a.name) CONTAINS 'news' OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'news')
         OR toLower(a.name) CONTAINS 'publisher' OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'publisher')
         OR toLower(a.name) CONTAINS 'journalism' OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'journalism'))
      )
      OR
      (
        (toLower(a.name) CONTAINS 'hardware' OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'hardware')
         OR toLower(a.name) CONTAINS 'annual' OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'annual'))
      )
    )
  )
  OR
  (
    (toLower(pub.name) CONTAINS 'the age' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'the age'))
    AND toLower(a.name) CONTAINS 'is google search better than the rest'
    AND toLower(a.name) CONTAINS 'fair'
  )
)
MATCH p=(a)-[*1..4]-(g:__Entity__)
WHERE toLower(g.name) CONTAINS 'google'
   OR any(alias IN coalesce(g.aliases, []) WHERE toLower(alias) CONTAINS 'google')
RETURN a.name AS article, pub.name AS publisher,
       [n IN nodes(p) | n.name] AS connection,
       [r IN relationships(p) | type(r)] AS relationships
LIMIT 10

